import {
    Table,
    TableNameColumn,
    IntegerColumn,
    StringColumn,
    BooleanColumn,
    DomainPathColumn,
    ScriptColumn,
    ReferenceColumn,
    DomainIdColumn,
    FieldNameColumn,
} from '../../db'

export const sys_script_client = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_table_trace: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sys_metadata',
    extensible: true,
    label: 'Client Script',
    name: 'sys_script_client',
    schema: {
        table: TableNameColumn({
            label: 'Table',
            tableReference: true,
        }),
        ui_type: IntegerColumn({
            default: '0',
            choices: {
                0: {
                    label: 'Desktop',
                    sequence: 1,
                },
                1: {
                    label: 'Mobile / Service Portal',
                    sequence: 2,
                },
                10: {
                    label: 'All',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'UI Type',
        }),
        condition: StringColumn({
            label: 'Condition / onClick',
            maxLength: 254,
        }),
        global: BooleanColumn({
            default: true,
            label: 'Global',
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        isolate_script: BooleanColumn({
            default: false,
            label: 'Isolate script',
        }),
        script: ScriptColumn({}),
        order: IntegerColumn({
            label: [
                {
                    hint: 'Order in which to run the script',
                    label: 'Order',
                    plural: 'Orders',
                },
            ],
        }),
        view: StringColumn({
            label: 'View',
        }),

        sys_overrides: ReferenceColumn({
            label: [
                {
                    hint: 'Script being overridden by the current record',
                    label: 'Overrides',
                    plural: 'Overrides',
                },
            ],
            referenceTable: 'sys_script_client',
        }),
        messages: StringColumn({
            label: [
                {
                    hint: "Text strings (one per line) available to the Client Script as localized messages using getMessage('[message]')",
                    label: 'Messages',
                    plural: 'Messages',
                },
            ],
            maxLength: 4000,
        }),
        name: StringColumn({
            label: 'Name',
        }),
        type: StringColumn({
            choices: {
                onCellEdit: {
                    label: 'onCellEdit',
                },
                onChange: {
                    label: 'onChange',
                },
                onLoad: {
                    label: 'onLoad',
                },
                onSubmit: {
                    label: 'onSubmit',
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Type',
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the script belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 4000,
        }),
        applies_extended: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Applies to extended tables',
                    label: 'Inherited',
                    plural: 'Inherited',
                },
            ],
        }),
        field: FieldNameColumn({
            dependent: 'table',
            label: 'Field name',
        }),
    },
    textIndex: true,
})
